struct modparams{ui modulus, generator;};
template<modparams const&ref>
struct modular{
	static constexpr ui const& MOD = ref.modulus;
	static modular generator(){ return modular(ref.generator); }
	ui value;
	modular(i64 v = 0){ normalize(v % MOD + MOD); }
	modular& normalize(ui v){
		value = v < MOD ? v : v - MOD;
		return *this;
	}
	modular operator-() const{ return modular() - *this; }
	modular& operator+=(const modular& rhs){ return normalize(value + rhs.value); }
	modular& operator-=(const modular& rhs){ return normalize(value + MOD - rhs.value); }
	modular& operator*=(const modular& rhs){
		value = (ull)value * rhs.value % MOD;
		return *this;
	}
	modular& operator/=(const modular& rhs){ return *this *= rhs.inverse(); }
	modular operator+(const modular& rhs) const{ return modular(*this) += rhs; }
	modular operator-(const modular& rhs) const{ return modular(*this) -= rhs; }
	modular operator*(const modular& rhs) const{ return modular(*this) *= rhs; }
	modular operator/(const modular& rhs) const{ return modular(*this) /= rhs; }
	modular exponentiate(int exp) const{
		modular base(*this), result(1);
		while(exp){
			if(exp & 1) result *= base;
			base *= base;
			exp >>= 1;
		}
		return result;
	}
	modular inverse() const{ return exponentiate(MOD - 2); }
	friend modular operator+(int x, const modular& y){ return modular(x) + y; }
	friend modular operator-(int x, const modular& y){ return modular(x) - y; }
	friend modular operator*(int x, const modular& y){ return modular(x) * y; }
	friend modular operator/(int x, const modular& y){ return modular(x) / y; }
	friend ostream& operator<<(ostream& os, const modular& m){ return os << m.value; }
	friend istream& operator>>(istream& is, modular& m){ i64 x; is >> x; m = modular(x); return is; }
	bool operator<(const modular& r) const{ return value < r.value; }
	bool operator==(const modular& r) const{ return value == r.value; }
	bool operator!=(const modular& r) const{ return value != r.value; }
	explicit operator bool() const{ return value; }
};

modparams modcfg{998244353, 3};
using mint = modular<modcfg>;

const int MAX_SIZE = 10010;
mint factorial_table[MAX_SIZE], inv_factorial_table[MAX_SIZE], modular_inverse[MAX_SIZE];
void initialize_factorials(){
	factorial_table[0] = 1;
	FOR_UP(i, 1, MAX_SIZE){
		factorial_table[i] = factorial_table[i - 1] * i;
	}
	inv_factorial_table[MAX_SIZE - 1] = factorial_table[MAX_SIZE - 1].inverse();
	for(int i = MAX_SIZE - 2; i >= 0; --i){
		inv_factorial_table[i] = inv_factorial_table[i + 1] * (i + 1);
	}
	for(int i = MAX_SIZE - 1; i >= 1; --i){
		modular_inverse[i] = inv_factorial_table[i] * factorial_table[i - 1];
	}
}
mint combination(int n, int k){
	return factorial_table[n] * inv_factorial_table[n - k] * inv_factorial_table[k];
}
mint binomial_coefficient(int a, int b){
	return factorial_table[a + b] * inv_factorial_table[a] * inv_factorial_table[b];
}
mint catalan(int n){
	return binomial_coefficient(n, n) - (n - 1 >= 0 ? binomial_coefficient(n - 1, n + 1) : 0);
}

void compute(){
	int n, m; cin >> n >> m >> modcfg.modulus;
	initialize_factorials();

	mint total;
	FOR_UP(length, 1, m){
		mint part1 = mint(length + 1).exponentiate(length) * length / (n - length) * inv_factorial_table[length];
		REPEAT(i, m - length){
			int j = i + length;
			mint part2 = mint(n - length).exponentiate(i) * inv_factorial_table[i];
			mint part3 = (n - j) * mint(n + 1).exponentiate(m - 1 - j) * factorial_table[j];
			total += part1 * part2 * part3;
		}
	}
	total *= mint(2).exponentiate(m - 1) * (n + 1 - m);
	output(total);
}

